#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { createClient } from './client.js';

interface CliFlags {
  text?: string;
  'text-file'?: string;
  'segments-file'?: string;
  'voice-id'?: string;
  'model-id'?: string;
  stability?: string;
  'similarity-boost'?: string;
  output?: string;
  'output-dir'?: string;
  'output-format'?: string;
  retries?: string;
  'api-key'?: string;
  help?: boolean;
}

function emitErrAndExit(error: string, message: string, extra?: Record<string, unknown>): never {
  process.stderr.write(JSON.stringify({ ok: false, error, message, ...(extra ?? {}) }) + '\n');
  process.exit(1);
}

function classifyErr(err: unknown): string {
  if (err && typeof err === 'object' && 'statusCode' in err) {
    const status = (err as { statusCode: number }).statusCode;
    if (status === 401 || status === 403) return 'auth';
    if (status === 402) return 'quota';
    if (status === 422) return 'policy';
    if (status === 429) return 'rate_limit';
    if (status >= 500) return 'upstream';
  }
  return 'unknown';
}

async function main(): Promise<void> {
  const { values } = parseArgs({
    options: {
      text: { type: 'string' },
      'text-file': { type: 'string' },
      'segments-file': { type: 'string' },
      'voice-id': { type: 'string' },
      'model-id': { type: 'string', default: 'eleven_multilingual_v2' },
      stability: { type: 'string', default: '0.5' },
      'similarity-boost': { type: 'string', default: '0.75' },
      output: { type: 'string' },
      'output-dir': { type: 'string' },
      'output-format': { type: 'string', default: 'mp3_44100_128' },
      retries: { type: 'string', default: '3' },
      'api-key': { type: 'string' },
      help: { type: 'boolean', short: 'h' },
    },
    strict: true,
  }) as { values: CliFlags };

  if (values.help) {
    process.stdout.write('See SKILL.md for full usage. Quick form:\n');
    process.stdout.write('  elevenlabs-tts --text "..." --voice-id <id> --output out.mp3\n');
    process.stdout.write('  elevenlabs-tts --segments-file segs.json --voice-id <id> --output-dir ./out/\n');
    process.exit(0);
  }

  const apiKey = values['api-key'] ?? process.env.ELEVENLABS_API_KEY;
  if (!apiKey) emitErrAndExit('config', 'Missing ELEVENLABS_API_KEY (or --api-key)');

  const voiceId = values['voice-id'];
  if (!voiceId) emitErrAndExit('config', '--voice-id is required');

  const modes = [values.text, values['text-file'], values['segments-file']].filter(Boolean);
  if (modes.length !== 1) {
    emitErrAndExit('config', 'Provide exactly one of --text, --text-file, --segments-file');
  }

  const client = createClient({
    apiKey,
    maxRetries: Number(values.retries ?? 3),
  });

  const baseReq = {
    voiceId,
    modelId: values['model-id'],
    stability: Number(values.stability),
    similarityBoost: Number(values['similarity-boost']),
    outputFormat: values['output-format'],
  };

  try {
    // Segments mode — array of {id, text} -> multiple files
    if (values['segments-file']) {
      const segRaw = await readFile(values['segments-file'], 'utf8');
      const segments = JSON.parse(segRaw) as Array<{ id: string; text: string }>;
      if (!Array.isArray(segments) || segments.length === 0) {
        emitErrAndExit('config', 'segments-file must be a non-empty JSON array of {id, text}');
      }
      const outDir = values['output-dir'];
      if (!outDir) emitErrAndExit('config', '--output-dir required when using --segments-file');
      await mkdir(outDir, { recursive: true });

      const outputs: string[] = [];
      let totalChars = 0;
      for (let i = 0; i < segments.length; i++) {
        const seg = segments[i];
        const pad = String(i + 1).padStart(2, '0');
        const outPath = path.join(outDir, `${pad}-${seg.id}.mp3`);
        const audio = await client.synthesize({ ...baseReq, text: seg.text });
        await writeFile(outPath, audio);
        outputs.push(outPath);
        totalChars += seg.text.length;
      }
      process.stdout.write(JSON.stringify({
        ok: true,
        outputs,
        voice_id: voiceId,
        model_id: baseReq.modelId,
        total_chars: totalChars,
        segments: segments.length,
      }) + '\n');
      return;
    }

    // Single-text modes
    let text: string;
    if (values['text-file']) {
      text = await readFile(values['text-file'], 'utf8');
    } else {
      text = values.text!;
    }

    if (!values.output) emitErrAndExit('config', '--output required when using --text or --text-file');

    const audio = await client.synthesize({ ...baseReq, text });
    await mkdir(path.dirname(values.output), { recursive: true });
    await writeFile(values.output, audio);

    process.stdout.write(JSON.stringify({
      ok: true,
      outputs: [values.output],
      voice_id: voiceId,
      model_id: baseReq.modelId,
      total_chars: text.length,
      bytes: audio.length,
    }) + '\n');
  } catch (err) {
    const kind = classifyErr(err);
    const message = err instanceof Error ? err.message : String(err);
    emitErrAndExit(kind, message);
  }
}

main().catch((err) => {
  emitErrAndExit('unknown', err instanceof Error ? err.message : String(err));
});

import { ElevenLabsClient as SDKClient } from 'elevenlabs';

export interface ClientConfig {
  apiKey: string;
  retryBaseDelayMs?: number;
  maxRetries?: number;
}

export interface SynthesisRequest {
  text: string;
  voiceId: string;
  modelId?: string;
  stability?: number;
  similarityBoost?: number;
  outputFormat?: string;
}

const DEFAULT_BASE_DELAY_MS = 1000;
const DEFAULT_MAX_RETRIES = 3;

function isRetryable(err: unknown): boolean {
  if (err && typeof err === 'object' && 'statusCode' in err) {
    const status = (err as { statusCode: number }).statusCode;
    return status === 429 || (status >= 500 && status <= 599);
  }
  return false;
}

async function withRetry<T>(fn: () => Promise<T>, baseDelayMs: number, maxRetries: number): Promise<T> {
  let lastErr: unknown;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      if (attempt < maxRetries && isRetryable(err)) {
        await new Promise(r => setTimeout(r, baseDelayMs * Math.pow(2, attempt)));
        continue;
      }
      throw err;
    }
  }
  throw lastErr;
}

export function createClient(cfg: ClientConfig) {
  const sdk = new SDKClient({ apiKey: cfg.apiKey });
  const baseDelay = cfg.retryBaseDelayMs ?? DEFAULT_BASE_DELAY_MS;
  const maxRetries = cfg.maxRetries ?? DEFAULT_MAX_RETRIES;

  async function synthesize(req: SynthesisRequest): Promise<Buffer> {
    if (!req.text || req.text.trim().length === 0) {
      throw new Error('synthesize: text must be non-empty');
    }

    return withRetry(async () => {
      const stream = await sdk.textToSpeech.convert(req.voiceId, {
        text: req.text,
        model_id: req.modelId ?? 'eleven_multilingual_v2',
        // SDK enum is strict at compile time; accepts any valid ElevenLabs format string at runtime
        output_format: (req.outputFormat ?? 'mp3_44100_128') as any,
        voice_settings: {
          stability: req.stability ?? 0.5,
          similarity_boost: req.similarityBoost ?? 0.75,
        },
      });

      const chunks: Buffer[] = [];
      for await (const chunk of stream as AsyncIterable<Uint8Array>) {
        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
      }
      const audio = Buffer.concat(chunks);
      if (audio.length === 0) {
        throw new Error('synthesize: ElevenLabs returned empty audio buffer');
      }
      return audio;
    }, baseDelay, maxRetries);
  }

  return { synthesize };
}

export type Client = ReturnType<typeof createClient>;

import { describe, expect, it, vi, beforeEach } from 'vitest';

// Mock the elevenlabs SDK before importing the client
vi.mock('elevenlabs', () => ({
  ElevenLabsClient: vi.fn().mockImplementation(() => ({
    textToSpeech: {
      convert: vi.fn(),
    },
  })),
}));

import { createClient } from '../src/client.js';
import { ElevenLabsClient as SDKClient } from 'elevenlabs';

function makeStreamFrom(buf: Buffer): AsyncIterable<Uint8Array> {
  return (async function* () {
    yield buf;
  })();
}

describe('elevenlabs-tts client', () => {
  beforeEach(() => { vi.clearAllMocks(); });

  it('synthesises non-empty text and returns the audio buffer', async () => {
    const fakeAudio = Buffer.from('FAKE_MP3_DATA');
    const sdk = {
      textToSpeech: { convert: vi.fn().mockResolvedValue(makeStreamFrom(fakeAudio)) },
    };
    (SDKClient as any).mockImplementationOnce(() => sdk);

    const c = createClient({ apiKey: 'test-key' });
    const out = await c.synthesize({ text: 'hello', voiceId: 'v1' });

    expect(out).toBeInstanceOf(Buffer);
    expect(out.equals(fakeAudio)).toBe(true);
    expect(sdk.textToSpeech.convert).toHaveBeenCalledWith('v1', expect.objectContaining({
      text: 'hello',
      model_id: 'eleven_multilingual_v2',
      output_format: 'mp3_44100_128',
      voice_settings: { stability: 0.5, similarity_boost: 0.75 },
    }));
  });

  it('rejects empty or whitespace-only text without calling the API', async () => {
    const sdk = { textToSpeech: { convert: vi.fn() } };
    (SDKClient as any).mockImplementationOnce(() => sdk);
    const c = createClient({ apiKey: 'k' });

    await expect(c.synthesize({ text: '', voiceId: 'v' })).rejects.toThrow(/non-empty/);
    await expect(c.synthesize({ text: '   \n  ', voiceId: 'v' })).rejects.toThrow(/non-empty/);
    expect(sdk.textToSpeech.convert).not.toHaveBeenCalled();
  });

  it('throws on empty audio buffer (no silent pass)', async () => {
    const sdk = {
      textToSpeech: { convert: vi.fn().mockResolvedValue(makeStreamFrom(Buffer.alloc(0))) },
    };
    (SDKClient as any).mockImplementationOnce(() => sdk);
    const c = createClient({ apiKey: 'k', maxRetries: 0 });

    await expect(c.synthesize({ text: 'hi', voiceId: 'v' })).rejects.toThrow(/empty audio/);
  });

  it('retries on 429 and succeeds on second attempt', async () => {
    const err429 = Object.assign(new Error('rate limited'), { statusCode: 429 });
    const convert = vi.fn()
      .mockRejectedValueOnce(err429)
      .mockResolvedValueOnce(makeStreamFrom(Buffer.from('ok')));
    (SDKClient as any).mockImplementationOnce(() => ({ textToSpeech: { convert } }));

    const c = createClient({ apiKey: 'k', retryBaseDelayMs: 1, maxRetries: 2 });
    const out = await c.synthesize({ text: 'hi', voiceId: 'v' });

    expect(out.toString()).toBe('ok');
    expect(convert).toHaveBeenCalledTimes(2);
  });

  it('does not retry on non-retryable errors (401 auth)', async () => {
    const err401 = Object.assign(new Error('unauthorized'), { statusCode: 401 });
    const convert = vi.fn().mockRejectedValue(err401);
    (SDKClient as any).mockImplementationOnce(() => ({ textToSpeech: { convert } }));

    const c = createClient({ apiKey: 'k', retryBaseDelayMs: 1, maxRetries: 5 });
    await expect(c.synthesize({ text: 'hi', voiceId: 'v' })).rejects.toThrow(/unauthorized/);
    expect(convert).toHaveBeenCalledTimes(1);
  });

  it('respects per-call voice + model overrides', async () => {
    const convert = vi.fn().mockResolvedValue(makeStreamFrom(Buffer.from('x')));
    (SDKClient as any).mockImplementationOnce(() => ({ textToSpeech: { convert } }));

    const c = createClient({ apiKey: 'k' });
    await c.synthesize({
      text: 'x',
      voiceId: 'CHARACTER_A',
      modelId: 'eleven_turbo_v2_5',
      stability: 0.8,
      similarityBoost: 0.3,
      outputFormat: 'opus_48000_64',
    });

    expect(convert).toHaveBeenCalledWith('CHARACTER_A', expect.objectContaining({
      model_id: 'eleven_turbo_v2_5',
      output_format: 'opus_48000_64',
      voice_settings: { stability: 0.8, similarity_boost: 0.3 },
    }));
  });
});
